{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would require each Tennessee public school district and public charter school to designate one instructional day each school year to teach students in kindergarten through grade 12 about the founding of the United States and the Fourth of July. Instruction must cover the separation of the original 13 colonies from Great Britain, the Declaration of Independence, the U.S. Constitution, and Americans’ fundamental rights and freedoms, with age- and grade-appropriate objectives for grades K–5, 6–8, and 9–12.",
      "rationale": "Conveys the annual instructional day, covered schools and students, required subjects, and age- and grade-appropriateness. The next paragraph expressly assigns annual designation to the directors."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Schools may choose the program and teaching methods, but instruction must meet the grade-specific objectives",
      "rationale": "Conveys local determination of programs and methods subject to mandatory grade-specific objectives. The illustrative teaching methods are not essential."
    },
    {
      "proposition_id": "P3",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Merely names the K–5 grade band without explaining its required learning outcomes concerning the holiday's meaning, independent nationhood, freedom and rights, or national symbols."
    },
    {
      "proposition_id": "P4",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe the grades 6–8 historical and civic learning outcomes. General subjects required across K–12 do not convey this grade band's specific requirements or its social studies option."
    },
    {
      "proposition_id": "P5",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe the grades 9–12 analytical learning outcomes, Revolution themes, historical and philosophical evaluation, citizenship connections, or English language arts option."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Each district and charter school director would have to designate the day annually, ensure consistent implementation, check compliance, and provide guidance as needed.",
      "rationale": "Conveys directors' responsibility for consistent implementation and guidance as needed across their schools."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Each district and charter school director would have to designate the day annually, ensure consistent implementation, check compliance, and provide guidance as needed. If instruction is part of social studies or English language arts, it must align with relevant state academic standards.",
      "rationale": "Conveys directors' compliance-checking duty and the conditional standards-alignment requirement. Omitting the standards' adopting body does not materially change the requirement."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "remain nonpartisan and educational, focused on historical facts, founding documents, and civic principles.",
      "rationale": "Conveys the required nonpartisan, educational character and prescribed historical, documentary, and civic focus."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "Schools must periodically review and may update their content, materials, and methods.",
      "rationale": "Conveys periodic review and discretionary updating, but omits the purposes of implementing civic-education best practices and ensuring applicable standards alignment through that review and updating."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law and apply beginning with the 2026–2027 school year.",
      "rationale": "Conveys immediate legal effectiveness and ongoing application starting in the specified school year."
    }
  ]
}
